    static void codecs(Path baselinePath) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        Set<PageCodec.Mode> modes = EnumSet.noneOf(PageCodec.Mode.class);
        int pages = 0;
        try (var baseline = baselinePath == null ? null : new BaselineCodec(baselinePath);
                var allocator = new NativeSlabAllocator(4L << 20)) {
            for (int seed = 0; seed < 8; seed++) {
                for (String kind : List.of("text", "prefix", "binary")) {
                    for (int flags = 0; flags < 16; flags++) {
                        boolean tokens = (flags & 1) != 0, vector = (flags & 2) != 0;
                        boolean adaptive = (flags & 4) != 0, prefix = (flags & 8) != 0;
                        int count = new int[]{1, 7, 16, 17, 63, 127, 255, 256}[seed];
                        PhysicalRecord[] records = Arrays.copyOf(OverlayBenchmark.corpus(seed, kind), count);
                        if (seed == 3) records[2] = new PhysicalRecord(new byte[0], false, 0);
                        if (seed == 5) records[3] = new PhysicalRecord(new byte[]{0, -1, 0, 'a', 0, -1, 0}, true, 7);
                        var page = PageCodec.seal(records, count, 16, 16, tokens, 1024, 48, vector, adaptive, prefix, 8);
                        modes.add(page.mode()); pages++;
                        digest.update(page.pageBytes());
                        long legacyHandle = baseline == null ? 0
                                : allocator.copy(baseline.encode(records, tokens, vector, adaptive, prefix));
                        long handle = allocator.copy(page.pageBytes());
                        for (int i = 0; i < records.length; i++) {
                            byte[] expected = records[i].bytes();
                            var decoded = PageCodec.read(allocator, handle, i);
                            check(Arrays.equals(expected, decoded.bytes()), "page full read " + page.mode());
                            check(decoded.large() == records[i].large(), "page LOB flag");
                            if (legacyHandle != 0) {
                                var old = PageCodec.read(allocator, legacyHandle, i);
                                check(Arrays.equals(expected, old.bytes()), "legacy page decoded bytes");
                                check(old.large() == records[i].large(), "legacy LOB flag");
                                RecordByteAccess legacy = PageCodec.openRecord(allocator, legacyHandle, i);
                                check(legacy.length() == expected.length, "legacy selective length");
                                byte[] oldCopy = new byte[expected.length];
                                legacy.copy(0, oldCopy, 0, oldCopy.length);
                                check(Arrays.equals(expected, oldCopy), "legacy selective copy");
                            }
                            RecordByteAccess record = PageCodec.openRecord(allocator, handle, i);
                            check(record.length() == expected.length, "selective length " + page.mode() + " seed=" + seed + " kind=" + kind + " flags=" + flags + " slot=" + i + " expected=" + expected.length + " actual=" + record.length());
                            byte[] output = new byte[expected.length];
                            record.copy(0, output, 0, output.length);
                            check(Arrays.equals(expected, output), "selective copy " + page.mode());
                            for (int j = expected.length - 1; j >= 0; j -= 3)
                                check(record.byteAt(j) == (expected[j] & 255), "backward byte access " + page.mode());
                            if (expected.length >= 3) {
                                Arrays.fill(output, (byte) 0);
                                int from = expected.length / 3, length = expected.length / 2;
                                record.copy(from, output, 1, length);
                                check(Arrays.equals(expected, from, from + length, output, 1, 1 + length), "partial copy");
                            }
                        }
                    }
                }
            }
        }
        check(modes.size() == PageCodec.Mode.values().length, "not all page modes exercised: " + modes);
        System.out.println("PASS " + pages + " codec pages, modes=" + modes + (baselinePath == null ? "" : ", exact decoded-record compatibility with input implementation"));
        System.out.println("CORPUS_SHA256=" + HexFormat.of().formatHex(digest.digest()));
    }

